class UsuarioLinkExtractor(FastHttpUser):
    wait_time = between(0.5, 1.5)   # pausa entre invocações

    @task
    def sequencia_de_10_invocacoes(self):
        urls = random.sample(URLS, k=len(URLS))  # 10 URLs
        for i, url in enumerate(urls):
            with self.client.get(f"/api/{url}",
                                 name=rotulo(url),
                                 catch_response=True) as resp:
                if resp.status_code != 200:
                    resp.failure(f"HTTP {resp.status_code}")
                elif len(resp.json()) != ESPERADO[url]:
                    resp.failure("quantidade de links errada")
                else:
                    resp.success()
            if i < len(urls) - 1:
                self.wait()   # pausa até a próxima URL

# URLS = 10 páginas http://127.0.0.1:8080/<pagina>.html
# ESPERADO = nº exato de links de cada página
# (trecho principal; arquivo completo: locust/locustfile.py)
